-- Batch 04: source-aware lexicographic review of horary, aspect and perfection terminology.
-- Direct witness: William Lilly, Christian Astrology, Book I, printed pp. 109–113 and 126–128.
-- Changes preserve all normalized schemes, source interpretations, citations and ontology; no formula rows altered.
PRAGMA foreign_keys=ON;

UPDATE term_article_sections SET heading='Two applications converge on one collector',body='In Lilly’s account, both principal significators cast their respective aspects toward a third, more ponderous planet. That planet is the common destination of the applications: it does not first separate from one significator and then carry its light to the other. Lilly further requires the two principals to receive the collector through their essential dignities (*Christian Astrology*, Book I, p. 126).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='collection-of-light') AND section_key='convergence';
UPDATE term_article_sections SET heading='Lilly’s additional reception requirement',body='Lilly’s description specifies both a weightier collecting planet and reception connected with the two principals. Those details should be used when explaining Lilly’s rule, but not presented as universal requirements of every author who describes collection. Compare Translation of Light, where the intermediary successively separates from one principal and applies to another.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='collection-of-light') AND section_key='lilly-reception';
UPDATE term_article_sections SET heading='Identify the relation in its source',body='Configuration can name a relationship of zodiacal signs, a planetary aspect, or a broader arrangement of celestial bodies, depending on the passage. A precise reading therefore requires identifying the figures or bodies involved and the relation the author actually describes; the English word alone does not prescribe one orb or an exact conjunction.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='configuration') AND section_key='reading';
UPDATE term_article_sections SET heading='A dexter sextile from Aries',body='Lilly illustrates the direction with a planet in Aries casting a sextile toward a planet in Aquarius: that is the dexter direction, contrary to the zodiacal succession. From Aries toward Gemini, the corresponding sextile is sinister. The planets’ approach toward or separation from an exact aspect is a separate question (*Christian Astrology*, Book I, p. 109).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='dexter-aspect') AND section_key='direction';
UPDATE term_article_sections SET heading='A sinister sextile from Aries',body='Lilly calls the sextile cast from Aries toward Gemini sinister because it follows the sequence of the signs. The opposite directional example, Aries toward Aquarius, is dexter. Both are sextiles: dexter and sinister specify which way the aspect is cast, not which type of aspect it is (*Christian Astrology*, Book I, p. 109).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='sinister-aspect') AND section_key='paired';
UPDATE term_article_sections SET heading='Direction and Lilly’s assessment of force',body='Dexter and sinister begin as geometrical directions, not automatic judgments of good and evil. Lilly explicitly describes the dexter aspect as stronger than the sinister in his discussion of aspectual direction (*Christian Astrology*, Book I, p. 109). That valuation is a named author''s assessment, not the definition of the directional terms themselves.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='sinister-aspect') AND section_key='not-good-bad';
UPDATE term_article_sections SET heading='Signs that do not behold',body='In traditional whole-sign geometry, inconjunct signs are not related by one of the five principal aspectual arrangements. Lilly gives Aries relative to Taurus or Scorpio among his examples of signs that do not behold each other (*Christian Astrology*, Book I, p. 109). This is a relation between signs, not a statement that no incidental degree-based contact can be calculated.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='inconjunct') AND section_key='geometry';
UPDATE term_article_sections SET heading='Lilly’s Mercury, Mars and Jupiter example',body='Lilly places Mercury at 10° Aries, Mars at 12° Aries and Jupiter at 13° Aries. Mercury is moving toward Mars, but Mars reaches Jupiter before Mercury can meet Mars. The first intended conjunction is therefore frustrated. The target’s contact with a third planet, not a reversal of Mercury’s motion, is the decisive event (*Christian Astrology*, Book I, pp. 112–113).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='frustration') AND section_key='target-acts-first';
UPDATE term_article_sections SET heading='Bodily prohibition and prohibition by aspect',body='Lilly separates two kinds of prohibition. In the bodily example, the Sun intervenes by conjunction before Mars and Saturn can perfect their intended conjunction. In the second, the Sun interposes its sextile to the relevant planets before their conjunction. Both depend on the third planet''s earlier contact, not on the applicant becoming retrograde (*Christian Astrology*, Book I, pp. 110–111).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='prohibition') AND section_key='forms';
UPDATE term_article_sections SET heading='The applicant turns back before perfection',body='Lilly illustrates refranation with Mars at 7° Aries applying toward Saturn at 12° Aries. Before the conjunction can perfect, Mars turns retrograde and withdraws from the approaching contact. Refranation is therefore a failed application caused by the applying planet''s own change of direction; it need not involve a third planet (*Christian Astrology*, Book I, p. 111).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='refranation') AND section_key='core-mechanics';
UPDATE term_article_sections SET heading='Exact separation and the remaining orb',body='Lilly distinguishes the beginning of separation from being entirely clear of the other planet’s rays. He describes Jupiter as separating from Saturn once it has moved several minutes beyond their exact conjunction, but reckons complete freedom from the contact only after the allowance of their combined half-orbs; in his example the latter totals nine degrees (*Christian Astrology*, Book I, p. 110).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='separation') AND section_key='mechanism';
UPDATE term_article_sections SET heading='Lilly''s sign-bound definition and its qualification',body='Lilly describes a planet as void of course after separation when, during the rest of its passage through the sign, it does not apply to another planet (*Christian Astrology*, Book I, p. 112). Later he qualifies the adverse judgment when the Moon is in Taurus, Cancer, Sagittarius or Pisces (p. 122). The recognition rule and the judgmental qualification are distinct; earlier authors'' alternative definitions still require separate verification.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='void-of-course') AND section_key='variants';
UPDATE term_article_sections SET heading='Names for interrogational astrology',body='Horary and interrogational astrology designate the branch in which an actual question supplies the subject of judgment. The historical vocabulary includes terms corresponding to question, interrogation and rooted question. A particular author''s divisions of question-types should be specified separately instead of treating every such division as another name for horary astrology.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='horary-question') AND section_key='historical-language';
UPDATE term_article_sections SET heading='Principal participants in a horary judgment',body='The querent is the person asking; the quesited is the person, object or matter asked about. In Lilly''s general approach the Ascendant and its lord signify the querent, while the appropriate topical house and its lord represent the quesited. Turning the houses allows subsidiary questions to be judged relative to the person or topic represented by that house (*Christian Astrology*, Book I, pp. 126–128).',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='horary-question') AND section_key='roles';
UPDATE term_article_sections SET heading='Degree-level exactness',body='Partile describes a particularly close degree-level agreement within an aspect type, rather than merely the fact that two signs are configured. The aspect can still be a sextile, square, trine or opposition; partile specifies its closeness to the corresponding degree. The precise numerical allowance should be taken from the particular author rather than supplied as an unqualified universal rule.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='partile-aspect') AND section_key='recognition';
UPDATE term_article_sections SET heading='Direct contact and mediation',body='Perfection can occur through the direct application of the relevant significators, or through a recognized form of mediation when they do not perfect with each other. Lilly describes translation and collection of light as such mediating forms (*Christian Astrology*, Book I, p. 126). These are distinct mechanics: translating light passes it onward; collecting light gathers two applications at one third planet.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='perfection') AND section_key='multiple-mechanics';
UPDATE term_article_sections SET heading='Swiftness is measured against the planet’s own norm',body='Swift in motion evaluates a planet''s longitudinal rate against a reference speed appropriate to that planet. It does not mean faster than another planet and does not by itself assert direct motion. Any particular average speed or threshold belongs to the author''s adopted astronomical tables or comparison rule.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='swift-in-motion') AND section_key='relative';
UPDATE term_article_sections SET heading='The turning points of direct and retrograde motion',body='A first station marks the planet''s apparent turn from direct toward retrograde motion; a second marks its return toward direct motion. Both belong to the same apparent longitudinal cycle, but the direction of the impending motion differs. Judgmental consequences must therefore be connected with the station concerned rather than inferred from the word ''station'' alone.',editorial_notes='Batch 04: source-aware explanation, distinct mechanism or verified Lilly illustration.' WHERE term_id=(SELECT id FROM terms WHERE slug='station') AND section_key='cycle';

UPDATE term_articles SET intro='In Lilly’s account, collection can bring two otherwise unconnected principal significators into contact through a weightier third planet. His reception condition is set out below; other source traditions should be evaluated on their own terms.',editorial_notes='Batch 04: definition-to-article redundancy reduced without changing technical identity.' WHERE term_id=(SELECT id FROM terms WHERE slug='collection-of-light');
UPDATE term_articles SET intro='In Lilly’s example, the slower planet that a faster applicant seeks reaches another conjunction first. The resulting interruption is distinct from an applicant turning retrograde (refranation) or a third planet interposing an aspect (prohibition).',editorial_notes='Batch 04: definition-to-article redundancy reduced without changing technical identity.' WHERE term_id=(SELECT id FROM terms WHERE slug='frustration');
UPDATE term_articles SET intro='An interrogational figure is judged from the operative moment of a particular question. The person asking, the matter asked about, and the relevant houses supply the subjects of the judgment; historical authors differ in their divisions of question types and rules for establishing the root time.',editorial_notes='Batch 04: definition-to-article redundancy reduced without changing technical identity.' WHERE term_id=(SELECT id FROM terms WHERE slug='horary-question');
UPDATE term_articles SET intro='Lilly distinguishes bodily prohibition from prohibition by aspect. Both describe a third planet interrupting the intended connection before the original significators can perfect their own contact.',editorial_notes='Batch 04: definition-to-article redundancy reduced without changing technical identity.' WHERE term_id=(SELECT id FROM terms WHERE slug='prohibition');
UPDATE term_articles SET intro='After exact contact, the planets may be described as separating while still remaining within their allotted rays. Lilly distinguishes the beginning of separation from complete freedom from the earlier aspect; these stages should not be treated as identical.',editorial_notes='Batch 04: definition-to-article redundancy reduced without changing technical identity.' WHERE term_id=(SELECT id FROM terms WHERE slug='separation');
UPDATE term_articles SET intro='The Moon is especially important in Lilly''s account of this sign-bound condition. He describes no further application within the sign, while separately qualifying the judgment in certain signs. Earlier and later definitions should be cited individually.',editorial_notes='Batch 04: definition-to-article redundancy reduced without changing technical identity.' WHERE term_id=(SELECT id FROM terms WHERE slug='void-of-course');
